<template>
 <section class="calibration-story" :class="{embedded}" aria-label="校准过程展示">
  <header class="story-header"><div><p class="eyebrow">数据进入模型，模型接受检验</p><h2>让预测有依据，让修正看得见</h2><p>先用历史数据学习参数，再用新到达的观测修正状态。两步各有自己的评价指标。</p></div><button v-if="!embedded" class="close" @click="$emit('close')">返回大棚 ×</button></header>
  <div v-if="error" class="load-error" role="status">{{ error }} <button @click="load">重新读取</button></div>
  <div v-if="!result" class="waiting">{{ loading?'正在读取已保存的校准结果…':'还没有可展示的历史校准结果，请在完整工作区创建。' }}</div>
  <template v-if="result">
   <ol class="learning-flow"><li><span>01 · 学习参数</span><h3>2023 / 2024</h3><p>同品种 CK 批次，用株高观测校准节间出现间隔和长度。</p></li><li><span>02 · 冻结机制</span><h3>{{ fmt(result.parameters.phyllochronGdd,2) }}<small>°Cd / 节间</small></h3><p>参数学习完成后固定，2025 年生长目标不参与拟合。</p></li><li><span>03 · 保留年份评价</span><h3>2025</h3><p>比较同一环境驱动下的原模拟与校准模型，不用拟合后的偏差代替预测误差。</p></li></ol>
   <div class="history-head"><div><h3>已完成的历史对照</h3><p>点是原始测量，线是模型；这是历史评价，当前大棚不会提前接收这些未来测量。</p></div><div class="years" role="group" aria-label="校准展示年份"><button v-for="season in result.seasons" :key="season.year" :class="{active:year===season.year}" :aria-pressed="year===season.year" @click="year=season.year">{{ season.year }}<small>{{ season.role==='holdout'?'评价':'校准' }}</small></button></div></div>
   <div class="comparison"><div class="plot-column"><div ref="chartRef" class="plot"></div><p class="chart-note">批次均值 · 株高 cm · 首日观测用于初始化；后续实测点不重置这条历史预测曲线。</p></div><aside class="score-column"><span class="eyebrow">{{ year===2025?'保留年份':'训练批次' }} · 配对误差</span><dl><div><dt>原模拟 RMSE</dt><dd>{{ fmt(season?.scores.original.rmse,2) }}<small>cm</small></dd></div><div class="corrected-score"><dt>校准模型 RMSE</dt><dd>{{ fmt(season?.scores.corrected.rmse,2) }}<small>cm</small></dd></div></dl><p>{{ season?.scores.corrected.n ?? 0 }} 个逐株配对点，排除首日初态。RMSE 越低表示这批株高预测误差越小。</p><p v-if="year===2025&&improvement!==null" :class="{improved:improvement>0}">{{ improvement>0?'误差降低':'误差增加' }} {{ fmt(Math.abs(improvement),1) }}% · 相对原模拟</p></aside></div>
  </template>
  <section class="online-section"><div class="online-head"><div><span class="eyebrow">在线状态纠偏</span><h3>预测 → 观测到达 → 修正</h3></div><span class="arrival">{{ run ? run.current.at.replace('T',' ') : '等待关联当前运行' }}</span></div>
   <div v-if="latest" class="update-flow"><div><span>本次观测前预测</span><strong>{{ fmt(latest.beforeCm,1) }}<small>cm</small></strong></div><i>→</i><div><span>M3 到达的实测</span><strong>{{ fmt(latest.observedCm,1) }}<small>cm</small></strong></div><i>→</i><div><span>吸收观测后的状态</span><strong>{{ fmt(latest.afterCm,1) }}<small>cm</small></strong></div></div>
   <p v-if="latest" class="online-copy">最近更新 {{ latest.at.replace('T',' ') }} · {{ latest.plantId }} · 观测权重 {{ fmt((latest.measurementWeight??0)*100,0) }}%。模型按不确定性吸收观测，并由新的状态继续预测。</p>
   <div v-else class="not-arrived"><b>{{ run?.updateCount ? '正在同步已到达的观测记录' : run?'持续预测，等待下一次测量':'关联运行后，显示本次真实的观测更新' }}</b><p>{{ run?.updateCount ? '已有 '+run.updateCount+' 次逐株更新，正在读取对应记录。' : run?'首日实测已建立初态。没有新株高观测到达时，模型只根据环境推进；不会为了展示生成虚假的测量点。':'历史参数校准结果已可查看；大棚在线时钟与逐株状态更新会在此独立展示。' }}</p></div>
   <div v-if="run" class="online-metrics"><span>累计更新<strong>{{ run.updateCount }}<small>次逐株</small></strong></span><span>新观测前预测 RMSE<strong>{{ fmt(run.scores.prior.rmse,2) }}<small>cm</small></strong></span><span>当次更新后拟合偏差<strong>{{ fmt(run.scores.posterior.rmse,2) }}<small>cm</small></strong></span></div>
   <p class="boundary">更新后的拟合偏差不是独立预测精度。株高校准不能证明果实、产量或设备响应已经准确。</p>
  </section>
  <footer class="story-foot"><span>当前展示：M3 原始观测 + 简化株高机制 + 观测状态更新</span><button @click="openWorkspace">完整校准工作区 →</button></footer>
 </section>
</template>
<script setup lang="ts">
import {computed,nextTick,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import {useRouter} from 'vue-router';
import * as echarts from 'echarts';
import {getM3Result,formatM3Number as fmt,type M3Result} from '/@/api/m3';
import type {M3LiveRun} from '/@/api/m3/live';
const props=defineProps<{run?:M3LiveRun|null;embedded?:boolean}>();defineEmits<{(e:'close'):void}>();
const router=useRouter(),result=ref<M3Result|null>(null),year=ref(2025),loading=ref(false),error=ref(''),chartRef=ref<HTMLDivElement>();
const season=computed(()=>result.value?.seasons.find(s=>s.year===year.value));
const latest=computed(()=>props.run?.events.filter(e=>e.type==='HEIGHT_UPDATE').slice(-1)[0]);
const improvement=computed(()=>{const a=season.value?.scores.original.rmse,b=season.value?.scores.corrected.rmse;return typeof a==='number'&&a>0&&typeof b==='number'?(a-b)/a*100:null;});
let chart:echarts.ECharts|undefined,observer:ResizeObserver|undefined,disposed=false;
async function load(){loading.value=true;error.value='';try{const value=await getM3Result();if(!disposed)result.value=value;}catch(e){if(!disposed)error.value=e instanceof Error?e.message:String(e);}finally{loading.value=false;await nextTick();draw();}}
function draw(){if(!chartRef.value||!season.value||disposed)return;if(!observer){observer=new ResizeObserver(()=>{if(chart)chart.resize();else draw();});observer.observe(chartRef.value);}if(!chartRef.value.clientWidth)return;if(!chart)chart=echarts.init(chartRef.value);const rows=season.value.series;chart.setOption({animation:false,color:['#ada695','#5e7b4e','#bd8e51'],legend:{top:3,icon:'circle',itemWidth:9,textStyle:{fontSize:12,color:'#7b846c'}},tooltip:{trigger:'axis',valueFormatter:(v:unknown)=>typeof v==='number'?v.toFixed(1)+' cm':'—'},grid:{left:52,right:15,top:38,bottom:30},xAxis:{type:'category',data:rows.map(r=>r.date),axisLabel:{formatter:(s:string)=>s.slice(5),color:'#999b87'},axisTick:{show:false},axisLine:{lineStyle:{color:'#dfe1d3'}}},yAxis:{type:'value',name:'株高 / cm',axisLabel:{color:'#999b87'},splitLine:{lineStyle:{color:'#e9ebdf'}}},series:[{name:'原模拟',type:'line',showSymbol:false,lineStyle:{type:'dashed',width:2},data:rows.map(r=>r.originalHeightCm)},{name:'校准后预测',type:'line',showSymbol:false,lineStyle:{width:3},data:rows.map(r=>r.correctedHeightCm)},{name:'M3 实测',type:'scatter',symbolSize:8,data:rows.map(r=>r.observedHeightCm)}]},true);}
function openWorkspace(){router.push({path:'/modelCalibration',query:props.run?{liveRun:props.run.runId}:{}});}
watch(year,async()=>{await nextTick();draw();});onMounted(load);onBeforeUnmount(()=>{disposed=true;observer?.disconnect();chart?.dispose();});
</script>
